#!/bin/bash
# health.sh - simple reusable system health report

DISK_THRESHOLD=${DISK_THRESHOLD:-80}   # percent, override via env

check_disk() {
  echo "== Disk usage =="
  df -h --output=target,pcent -x tmpfs -x devtmpfs | tail -n +2 | while read -r mount pct; do
    used=${pct%\%}
    if [ "$used" -ge "$DISK_THRESHOLD" ]; then
      echo "WARNING: $mount is ${used}% full"
    else
      echo "OK: $mount ${used}%"
    fi
  done
}

check_memory() {
  echo "== Memory =="
  free -h
}

check_uptime() {
  echo "== Uptime / load =="
  uptime
}

for section in check_disk check_memory check_uptime; do
  "$section"
  echo
done
